import 'package:mad_flutter_practicum/domain/domain.dart';

import '../currency_list/widgets/currency_card.dart';
import '../news_list/widgets/news_card.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<Map<String, dynamic>> _dashboardFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) {
      return <String, dynamic>{
        'currencyPage': results[0] as CurrencyPage,
        'news': results[1] as List<NewsModel>,
      };
    });
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<Map<String, dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<Map<String, dynamic>> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (snapshot.hasError) {
            return Center(
              child: Text(
                'Error: ${snapshot.error}',
                style: context.fonts.regular16,
              ),
            );
          }

          final Map<String, dynamic>? data = snapshot.data;
          if (data == null) {
            return const Center(child: CircularProgressIndicator());
          }

          final CurrencyPage currencyPage = data['currencyPage'] as CurrencyPage;
          final List<NewsModel> newsList = data['news'] as List<NewsModel>;

          return ListView(
            padding: const EdgeInsets.symmetric(vertical: 16),
            children: [
              // Currency section
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 8, 20, 0),
                child: Text(
                  loc.currencyRate,
                  style: context.fonts.regular16.copyWith(fontWeight: FontWeight.bold),
                ),
              ),
              ...currencyPage.items.map((CurrencyModel currency) {
                return Padding(
                  padding: const EdgeInsets.fromLTRB(20, 8, 20, 0),
                  child: CurrencyCard(model: currency),
                );
              }),
              // News section
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 16, 20, 0),
                child: Text(
                  loc.news,
                  style: context.fonts.regular16.copyWith(fontWeight: FontWeight.bold),
                ),
              ),
              ...newsList.map((NewsModel news) {
                return Padding(
                  padding: const EdgeInsets.fromLTRB(20, 8, 20, 0),
                  child: NewsCard(model: news),
                );
              }),
            ],
          );
        },
      ),
    );
  }
}
